/* ---------- Roadmap-Grafik (SVG), Zeitachse: Q4/2026–2028 im Quartalsraster, 2029–2031 im Jahresraster ---------- */
const RMC={W:1200,LW:214,X0:224,K:70.8,RH:66,Y0:52};
function rmX(d){const [y,m,t]=d.split('-').map(Number),mo=(y-2026)*12+(m-10)+(t-1)/new Date(y,m,0).getDate(),q=.35*RMC.K,yr=1.4/12*RMC.K;return RMC.X0+(mo<=27?mo*q:27*q+(mo-27)*yr)}
const rmIn=x=>RMC.X0+(x-4.85)*RMC.K;
const rmTop=i=>RMC.Y0+i*RMC.RH,rmCy=i=>rmTop(i)+33;
function rmLines(n){if(n.includes(' & '))return [n.split(' & ')[0]+' &',n.split(' & ')[1]];if(n.length>16&&n.includes(' ')){const k=n.lastIndexOf(' ');return [n.slice(0,k),n.slice(k+1)]}return [n]}
function rmChart(V){const C=RMC,n=V.rows.length,yEnd=rmTop(n);let s='';
 const years=[['2026','2026-10-01','2027-01-01'],['2027','2027-01-01','2028-01-01'],['2028','2028-01-01','2029-01-01'],['2029','2029-01-01','2030-01-01'],['2030','2030-01-01','2031-01-01'],['2031','2031-01-01','2032-01-01']];
 s+=`<rect x="0" y="0" width="${C.LW}" height="${yEnd}" class="labcol"/><text x="14" y="30" class="hd">Teilprojekt · Status</text>`;
 years.forEach(([t,a,b])=>{const xa=rmX(a),xb=rmX(b);s+=`<rect x="${xa}" y="0" width="${xb-xa-2}" height="24" class="yr"/><text x="${t==='2026'?xa+8:(xa+xb)/2}" y="16.5" text-anchor="${t==='2026'?'start':'middle'}" class="yt">${t}</text>`});
 const qs=[['Q4','2026-10-01','2027-01-01']];['2027','2028'].forEach(y=>['01','04','07','10'].forEach((m,k)=>qs.push(['Q'+(k+1),`${y}-${m}-01`,k<3?`${y}-${['04','07','10'][k]}-01`:`${+y+1}-01-01`])));
 qs.forEach(([t,a,b],k)=>s+=`<text x="${k?(rmX(a)+rmX(b))/2:rmX(a)+8}" y="40" text-anchor="${k?'middle':'start'}" class="qt">${t}</text>`);
 s+=`<text x="${(rmX('2029-01-01')+C.W)/2}" y="40" text-anchor="middle" class="qt it2">Jahresraster</text>`;
 V.rows.forEach((r,i)=>{const y=rmTop(i);
  s+=`<g class="rrow${RM.sel===i?' sel':''}" data-rmsel="${i}" tabindex="0" role="button" aria-label="${esc(r.name)}: Details zeigen"><rect x="${C.X0-6}" y="${y}" width="${C.W-C.X0+6}" height="${C.RH}" class="band ${i%2?'b':'a'}"/><rect x="0" y="${y}" width="${C.LW}" height="${C.RH}" class="lhit"/>${RM.sel===i?`<rect x="0" y="${y+8}" width="3" height="${C.RH-16}" fill="${RM_COL.gate}"/>`:''}
   <rect x="12" y="${y+16}" width="34" height="34" class="rtile"/><svg x="19" y="${y+23}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="${RM_COL.gate}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${RM_ICONS[r.icon]||''}</svg>
   <circle cx="60" cy="${y+33}" r="6.5" fill="${RM_ST[r.st][1]}"/>`;
  const L=rmLines(r.name);s+=`<text x="74" y="${y+(L.length>1?29:37.5)}" class="rn">${L.map((t,k)=>`<tspan x="74" dy="${k?16:0}">${esc(t)}</tspan>`).join('')}</text></g>`;});
 // Raster
 qs.slice(1).forEach(([t,a])=>s+=`<line x1="${rmX(a)}" x2="${rmX(a)}" y1="46" y2="${yEnd}" class="${t==='Q1'?'gy':'gq'}"/>`);
 ['2030-01-01','2031-01-01'].forEach(a=>s+=`<line x1="${rmX(a)}" x2="${rmX(a)}" y1="46" y2="${yEnd}" class="gy"/>`);
 s+=`<line x1="${rmX('2029-01-01')}" x2="${rmX('2029-01-01')}" y1="46" y2="${yEnd}" class="gs"/>`;
 const td=new Date().toISOString().slice(0,10);
 if(td>='2026-10-01'&&td<'2032-01-01'){const x=rmX(td);s+=`<line x1="${x}" x2="${x}" y1="26" y2="${yEnd+4}" class="today"/><text x="${x}" y="${yEnd+18}" text-anchor="middle" class="qt">heute</text>`}
 // Elemente
 const tip=(it,r)=>{const l=(r.items||[]).find(o=>o.t==='lab'&&o.d===it.d&&!/^Gelb/.test(o.text));return esc((l?l.text+' · ':'')+(it.t==='dia'?RM_KIND[it.kind]:it.dir==='start'?'Start':'Ende')+' · '+rmD(it.d)+(it.planned?' (erwartet)':''))};
 V.rows.forEach((r,i)=>{const cy=rmCy(i);let g='';
  (r.items||[]).forEach(it=>{
   if(it.t==='bar'){const x1=rmX(it.s),x2=rmX(it.e),y=rmTop(i)+22,h=22,tp=Math.min(9,(x2-x1)/3);
    g+=`<g class="el"><title>${esc((it.text?it.text+' · ':'')+rmD(it.s)+' bis '+rmD(it.e)+(it.style==='dot'?' (erwartet, nach Gate)':''))}</title><path d="M${x1} ${y}H${x2-tp}L${x2} ${y+h/2}L${x2-tp} ${y+h}H${x1}Z" class="ph ${it.style}"/>${it.text?`<text x="${(x1+x2-tp)/2+1}" y="${y+15.5}" text-anchor="middle" class="pt ${it.style}"${it.fs?` style="font-size:${it.fs}px"`:''}>${esc(it.text)}</text>`:''}</g>`}
   if(it.t==='track')g+=`<line x1="${rmX(it.s)}" x2="${rmX(it.e)}" y1="${cy}" y2="${cy}" class="track"/>`;
  });
  (r.items||[]).forEach(it=>{
   if(it.t==='dia'){const c=RM_COL[it.kind],x=rmX(it.d)+(it.dx||0)*RMC.K,q=8.5;
    g+=`<g class="el"><title>${tip(it,r)}</title><path d="M${x} ${cy-q}L${x+q} ${cy}L${x} ${cy+q}L${x-q} ${cy}Z" fill="${it.planned?'#050608':c}" stroke="${it.planned?c:'#050608'}" stroke-width="${it.planned?1.6:.8}"${it.planned?' stroke-dasharray="3 2"':''}/>${it.num?`<text x="${x}" y="${cy+3.5}" text-anchor="middle" class="dn" fill="${it.planned?c:'#050608'}">${it.num}</text>`:''}</g>`}
   if(it.t==='tri'){const c=it.dir==='start'?RM_COL.start:RM_COL.end,x=rmX(it.d)+(it.dx||0)*RMC.K,w=8,h=9,p=it.dir==='start'?`M${x-w} ${cy-h}L${x+w} ${cy}L${x-w} ${cy+h}Z`:`M${x+w} ${cy-h}L${x-w} ${cy}L${x+w} ${cy+h}Z`;
    g+=`<g class="el"><title>${tip(it,r)}</title><path d="${p}" fill="${it.planned?'#050608':c}" stroke="${c}" stroke-width="${it.planned?1.6:.8}"${it.planned?' stroke-dasharray="3 2"':''}/></g>`}
   if(it.t==='lab'){const x=it.x!==undefined?rmIn(it.x):rmX(it.d)+(it.dx||0)*RMC.K,a=it.align==='l'?'start':it.align==='r'?'end':'middle',xx=it.align==='l'?x-7:it.align==='r'?x+7:x,y=it.pos==='above'?rmTop(i)+15:rmTop(i)+60,c=it.color?(RM_HEX[it.color]||'#'+it.color):'';
    g+=`<text x="${xx}" y="${y}" text-anchor="${a}" class="lb${it.bold?' b':''}"${c?` fill="${c}"`:''}${it.fs?` style="font-size:${Math.min(it.fs,12)}px"`:''}>${esc(it.text)}</text>`}
  });
  s+=`<g class="items" data-rmsel="${i}">${g}</g>`;});
 (V.links||[]).forEach(lk=>{const x1=rmX(lk.from.d),y1=rmCy(lk.from.row),x2=rmX(lk.to.d),y2=rmCy(lk.to.row);
  s+=`<g class="link"><path d="M${x1} ${y1}V${y2}H${x2}"/><circle cx="${x1}" cy="${y1}" r="4"/><circle cx="${x2}" cy="${y2}" r="4"/>${lk.text?`<text x="${rmIn(lk.textX)}" y="${rmTop(lk.textRow)+15}" class="lk">${esc(lk.text)}</text>`:''}</g>`});
 return {svg:s,h:yEnd+26};
}
function rmLegend(){const d=(c,dash)=>`<svg width="16" height="16" viewBox="0 0 16 16"><path d="M8 1L15 8L8 15L1 8Z" fill="${dash?'#050608':c}" stroke="${c}" ${dash?'stroke-dasharray="3 2" stroke-width="1.5"':'stroke-width="0"'}/></svg>`;
 return `<div class="rm-legend">
 <span><svg width="14" height="16" viewBox="0 0 14 16"><path d="M1 1L13 8L1 15Z" fill="${RM_COL.start}"/></svg>Projektstart</span>
 <span><svg width="14" height="16" viewBox="0 0 14 16"><path d="M13 1L1 8L13 15Z" fill="${RM_COL.end}"/></svg>Projektende</span>
 <span><svg width="66" height="14" viewBox="0 0 66 14"><path d="M0 1H18L22 7L18 13H0Z" fill="#4b4f58"/><path d="M22 1H40L44 7L40 13H22Z" fill="#868b96"/><path d="M44 1H60L64 7L60 13H44Z" fill="#d0d4db"/></svg>Phase, Budgetstufe 1 frei</span>
 <span><svg width="40" height="14" viewBox="0 0 40 14"><path d="M1 1H34L39 7L34 13H1Z" fill="none" stroke="#8b909a" stroke-dasharray="4 3"/></svg>Erwartet, nach Gate-Entscheid</span>
 <span>${d(RM_COL.gate)}Gate / Budgetfreigabe</span><span>${d(RM_COL.qg)}Genehmigung, Vertrag, Abnahme</span><span>${d(RM_COL.ms)}Kunden-Meilenstein</span>
 <span><svg width="40" height="12" viewBox="0 0 40 12"><path d="M5 6H35" stroke="${RM_COL.link}" stroke-width="2"/><circle cx="5" cy="6" r="4" fill="${RM_COL.link}"/><circle cx="35" cy="6" r="4" fill="${RM_COL.link}"/></svg>Fachübergreifend</span>
 <span>${['g','y','r'].map(k=>`<i class="sd" style="background:${RM_ST[k][1]}"></i>`).join('')}Status</span></div>`}
function rmDetail(V){const i=Math.min(Math.max(RM.sel|0,0),V.rows.length-1),r=V.rows[i],t2=V.t2[i];
 const warn=(r.items||[]).find(o=>o.t==='lab'&&/^Gelb/.test(o.text));
 const ms=(r.items||[]).filter(o=>o.t==='dia').map(o=>{const l=(r.items||[]).find(x=>x.t==='lab'&&x.d===o.d&&!/^Gelb/.test(x.text));return {o,txt:l?l.text:RM_KIND[o.kind]}});
 if(i===0)return `<section class="rm-detail"><div><div class="hd"><span class="rm-ic">${rmIcon('flag',26)}</span><div><span class="x-up lbl">Gesamtprojekt</span><h3>${esc(V.titles.rm)}</h3></div></div><p class="muted">${esc(RM_X[RM.v].crit)}</p></div>
  <div><span class="x-up lbl">Gates</span><ul class="rm-ms">${RM_X[RM.v].gates.map(g=>`<li><i class="md" style="background:${RM_COL.gate}"></i><span><b>${esc(g[0])} · ${esc(g[1])} · ${esc(g[2])}</b><br><span class="muted">${esc(g[3])}</span></span></li>`).join('')}</ul></div></section>`;
 const t1=V.t1[i-1];
 return `<section class="rm-detail"><div><div class="hd"><span class="rm-ic">${rmIcon(t1.icon,26)}</span><div><span class="x-up lbl">Teilprojekt ${i}</span><h3>${esc(t1.name)}</h3></div>${rmChip(t2.st)}</div>
  ${warn?`<p class="warn">${esc(warn.text)}</p>`:''}
  <dl><dt>Inhalt</dt><dd>${esc(t1.inhalt)}</dd><dt>Ziel</dt><dd>${esc(t1.ziel)}</dd><dt>PL</dt><dd>${esc(t2.pl)}</dd><dt>Collab.</dt><dd>${esc(t2.col)}</dd><dt>Budget</dt><dd>${esc(t2.bud)} T. USD${t2.pot!=='–'?` · Potential ${esc(t2.pot)} Mio USD`:''}</dd></dl></div>
  <div><span class="x-up lbl">Meilensteine</span><ul class="rm-ms">${ms.map(({o,txt})=>`<li><i class="md${o.planned?' pl':''}" style="--c:${RM_COL[o.kind]}"></i><span><b>${esc(txt)}</b><br><span class="muted">${esc(RM_KIND[o.kind])} · ${rmD(o.d)}${o.planned?' · erwartet':''}</span></span></li>`).join('')||'<li class="muted">Keine Meilensteine in dieser Zeile.</li>'}</ul></div></section>`;
}
function vRmMap(){const V=rmV(),C=rmChart(V);
 return rmHead('Roadmap · Format nach Prof. Hube','Die Roadmap',V.titles.rm)+rmLegend()+
 `<div class="rm-chartwrap"><svg class="rm-chart" viewBox="0 0 ${RMC.W} ${C.h}" role="group" aria-label="Roadmap ${esc(V.short)}">${C.svg}</svg></div>
 <p class="fine">Zeile anklicken für Details, Elemente antippen oder überfahren für Datum und Bezeichnung. Bis Ende 2028 Quartalsraster, ab 2029 Jahresraster.</p>`+rmDetail(V);
}
function vRmSrc(){const V=rmV();
 return rmHead('Recherche · Belege','Quellen und Annahmen',V.titles.src)+
 `<section class="rm-src"><div><h3 class="x-up">Recherche zur Durchführung</h3><ol>${V.sources.map(s=>`<li>${esc(s.fact)} – ${s.links.map(l=>l.url?`<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.by)}</a>`:`<span class="muted">${esc(l.by)}</span>`).join('; ')}</li>`).join('')}</ol></div>
  <div><h3 class="x-up">Annahmen und Abgleich</h3><ul>${V.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>
   <h3 class="x-up" style="margin-top:32px">Folien zum Download</h3>
   <div class="rm-dl">${['A','B'].map(k=>`<a class="xbtn${RM.v===k?' solid':''}" href="praesentation/${encodeURI(RM_DATA[k].file)}" download>${rmIcon('download',20)}Variante ${k} · PPTX</a>`).join('')}</div>
   <p class="fine" style="margin-top:12px">Je sechs Folien im Design der Gruppenpräsentation (20 × 11,25 Zoll), mit Sprechernotizen.</p></div></section>`;
}
document.getElementById('view').addEventListener('click',e=>{if(ui.ctx!=='dinner')return;const t=e.target.closest('[data-rmv],[data-rmgo],[data-rmsel]');if(!t)return;
 if(t.dataset.rmv){RM.v=t.dataset.rmv;rmSave();render(true);return}
 if(t.dataset.rmgo!==undefined){RM.sel=+t.dataset.rmgo;rmSave();go('rmmap');return}
 if(t.dataset.rmsel!==undefined){RM.sel=+t.dataset.rmsel;rmSave();render(true);const d=document.querySelector('.rm-detail');if(d&&d.getBoundingClientRect().top>innerHeight)d.scrollIntoView({behavior:'smooth',block:'nearest'})}});
document.getElementById('view').addEventListener('keydown',e=>{const t=e.target.closest&&e.target.closest('g[data-rmsel]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();t.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
